mapper.select:
select
    c.user_id           as userId,
    if(cr.status, 1, 0) as correct,
    cr.score            as score
from user_contest c
left join contest_records cr on cr.user_id = c.user_id
   and cr.problem_id = #{problemId}
   and cr.contest_id = #{contestId}
where
    c.contest_id = #{contestId}
